[
  {
    "slot_number": "slot-8-1-3",
    "slot_key": "Recovery expectations after outage or reboot",
    "slot_value": "While disconnected, records should queue locally and then sync automatically once the vessel reconnects, so nothing is lost; any conflicts or incomplete items should be flagged for review rather than silently overwritten, and submission status should be very clear so the crew knows what has gone through and what still needs attention. If the system has been offline long enough that stored context may be stale, the crew should be asked to enter or confirm it, and if there is a mismatch between onboard systems and what the crew sees, the user should be prompted to confirm before the record is submitted. The system should also carry over vessel identity, the active voyage or trip, the current date and time, and any known trip details already established on board, like home port or planned landing port if they’re still valid, and prompt the crew to confirm or refresh that context whenever the trip changes, the vessel is in a different port, the system has been offline, or imported data conflicts with crew expectations.",
    "operation": "refine"
  }
]

